#!/bin/sh
# queue stub: adopt --lane <id> [--if-free]
case "$3" in
  lane:held) echo 'REFUSED: held: holder=22222222 kind=process lane=lane:held'; exit 3 ;;
  lane:odd) echo 'held by 22222222'; exit 1 ;;
  lane:other) echo 'adopted lane:zzz'; exit 0 ;;
  *) echo "adopted $3"; exit 0 ;;
esac
